const ROUNDS = [{"name": "AIM", "title": "Where do we place our first bet?", "theme": "Ambition, strategic priorities and business value", "scenario": "Several departments want AI projects, but you can fund only one key initiative. Which would you prioritise?", "options": [{"title": "Solve an immediate problem", "body": "Address an urgent operational issue with a clear near-term benefit."}, {"title": "Back a strategic priority", "body": "Support a major business objective whose benefits will take longer to emerge."}, {"title": "Explore a new opportunity", "body": "Test a new customer proposition with uncertain but potentially substantial value."}], "discuss": "What does business value mean here? What evidence would justify your choice?", "twists": ["The board wants results in 90 days.", "Your strongest sponsor leaves. Who still owns the business outcome?"], "challenge": "What result will you measure, against which baseline, and by when?"}, {"name": "ENGAGE", "title": "Why is nobody using it?", "theme": "Leadership, people, culture and adoption", "scenario": "An AI assistant is available, but employees rarely use it. Some distrust its outputs.  Others worry about their roles. Where do you start?", "options": [{"title": "Lead by example", "body": "Ask leaders to model useful applications and discuss limitations openly."}, {"title": "Design with employees", "body": "Invite employees to redesign a workflow around a problem they care about."}, {"title": "Create space to practice", "body": "Provide protected time, support and peer champions to build confidence."}], "discuss": "What is stopping adoption? What should change in our leadership behaviour?", "twists": ["A respected manager says the tool threatens team expertise.", "Early users report extra checking work. Usage is rising, but time savings are not."], "challenge": "Which workflow and employee concern will you address first?"}, {"name": "EXPERIMENT", "title": "One more try, or time to stop?", "theme": "Learn fast, fail fast, iterate and innovate", "scenario": "A bounded AI pilot has mixed results. Some users see promise, but it has  missed its agreed success criteria. What happens next?", "options": [{"title": "Stop and share", "body": "Close the pilot and share what the team learned."}, {"title": "Iterate once more", "body": "Run one further test focused on the main weakness."}, {"title": "Try a different use case", "body": "Test another application suggested by the findings."}], "discuss": "What would make another iteration worthwhile? When would we stop?", "twists": ["The next iteration needs another month of scarce specialist time.", "A positive result comes from only two enthusiastic users."], "challenge": "Set a measurable success threshold and a stop rule."}, {"name": "PROTECT", "title": "What must we resolve before launch?", "theme": "Governance, security, privacy and responsible AI", "scenario": "A team proposes an AI assistant that uses customer records to recommend responses. Before live use, which question leads your review?", "options": [{"title": "Data and access", "body": "Are data use, security controls and privacy safeguards appropriate?"}, {"title": "Outputs and accountability", "body": "How will we test inaccurate or unfair advice and maintain human oversight?"}, {"title": "Ownership and response", "body": "Who approves the use case, monitors it and responds when something goes wrong?"}], "discuss": "All three need attention. How do we connect them? What would block launch?", "twists": ["A customer asks how their records influence recommendations.", "The assistant gives plausible but incorrect advice during a high-pressure interaction."], "challenge": "Name a launch blocker, a human decision owner, and an escalation route."}, {"name": "ENABLE", "title": "What is really blocking progress?", "theme": "Data, technology, skills and operating model", "scenario": "A promising initiative is stalled. Data is inconsistent, systems do not connect easily and ownership is unclear. Where do you begin?", "options": [{"title": "Fix essential data", "body": "Improve the data needed for the use case and assign data owners."}, {"title": "Connect the technology", "body": "Establish the integration needed for a limited deployment."}, {"title": "Clarify how we work", "body": "Create a cross-functional team with decision rights and targeted skills support."}], "discuss": "What is the immediate bottleneck? Which dependencies would remain?", "twists": ["You can resolve only one dependency this month.", "The proposed integration would create a second, conflicting source of customer data."], "challenge": "Name the critical dependency, its owner, and a bounded first release."}, {"name": "OPTIMISE", "title": "Are we getting value for our spend?", "theme": "AI FinOps, investment, consumption, cost and ROI", "scenario": "AI usage and spending are rising, but teams cannot clearly explain the benefits.  What is your first move?", "options": [{"title": "Make spending visible", "body": "Track consumption and cost by team and use case."}, {"title": "Improve efficiency", "body": "Test lower-cost models and usage patterns against quality requirements."}, {"title": "Review the investment", "body": "Compare costs with demonstrated outcomes and redirect funding."}], "discuss": "What evidence distinguishes useful growth from waste? How will we assess ROI?", "twists": ["Usage doubles next month with no extra budget.", "A cheaper model reduces costs but misses important exceptions."], "challenge": "Choose a unit-cost metric and an outcome metric, plus a quality floor."}, {"name": "SCALE", "title": "How do we take this beyond the pilot?", "theme": "Industrialise, measure impact and continuously reinvent", "scenario": "A successful AI pilot is ready for wider use, but departments have different workflows  and support needs. How do you expand?", "options": [{"title": "Standardise first", "body": "Establish common processes, support and reliability before wider rollout."}, {"title": "Expand in stages", "body": "Check impact and reliability at each stage before adding more teams."}, {"title": "Reuse and adapt", "body": "Create a common core that teams can adapt within agreed boundaries."}], "discuss": "What stays consistent? What can vary? When should we rethink the solution?", "twists": ["One department needs a materially different workflow.", "Quality drops after a data change in a newly onboarded department."], "challenge": "Define the rollout gate, what teams can adapt, and a rollback trigger."}];
